Lemma lb_bytes_cons : forall p A n LB, lb_bytes ((p, A, n) :: LB) = n + lb_bytes LB.
Proof. reflexivity. Qed.

(* [comment removed for export] *)
Lemma xpres_drop_fresh : forall s' LB m0 p A n SP X m m',
  as_RHEAP H s' ((p, A, n) :: LB) m0 -> aceil <= SP ->
  xpres H LB SP (X ++ [(A, A + n); (sh A, sh A + nsh n)])%Z m m' -> xpres H LB SP X m m'.
Proof.
  intros s' LB m0 p A n SP X m m' HP CE XP a Ha [HC NX]. apply XP; [exact Ha|]. split; [exact HC|].
  destruct (fresh_block_not_old_client H HH _ _ _ _ _ _ _ _ HP CE HC) as [N1 N2].
  intros K. apply rin_ivs_app in K. destruct K as [K|K]; [exact (NX K)|]. cbn in K. tauto.
Qed.

Lemma scratch_off_img : forall LF m XS, as_RFS H LF m -> Forall (fs_scratch H LF) XS ->
  Forall (fun iv : Z * Z => 0x12a180 <= fst iv \/ snd iv <= 0x119000) XS.
Proof.
  intros LF m XS RF FX. eapply Forall_impl; [| exact FX]. intros iv FS.
  pose proof (scratch_facts H HH LF m [] iv RF FS) as (_ & K & _). unfold AIMG_TOP in K. left. lia.
Qed.

